PLURALS = {
 "datetime_months_relative": {"one": "%1$d నెల క్రితం", "other": "%1$d నెలల క్రితం"},
 "datetime_years_relative": {"one": "%1$d సంవత్సరం క్రితం", "other": "%1$d సంవత్సరాల క్రితం"},
}

def esc(t):
    # text already pre-escaped for XML-relevant quotes; Android string body keeps literal \n and \" as authored
    return t

with open(TF, 'r', encoding='utf-8') as f:
    content = f.read()
original = content

# --- replace existing <string> keys ---
replaced = []
for k, v in STRINGS.items():
    pat = re.compile(r'(<string name="' + re.escape(k) + r'">).*?(</string>)', re.DOTALL)
    if pat.search(content):
        content = pat.sub(lambda m, _v=v: m.group(1) + _v + m.group(2), content, count=1)
        replaced.append(k)

# --- replace plurals ---
for k, items in PLURALS.items():
    block = '<plurals name="%s">\n        <item quantity="one">%s</item>\n        <item quantity="other">%s</item>\n    </plurals>' % (
        k, items["one"], items["other"])
    pat = re.compile(r'<plurals name="' + re.escape(k) + r'">.*?</plurals>', re.DOTALL)
    if pat.search(content):
        content = pat.sub(lambda m: block, content, count=1)
        replaced.append(k)

# --- insert NEW paywall_monthly_note (if not present) ---
inserted = []
NEWKEY = "paywall_monthly_note"
if ('name="%s"' % NEWKEY) not in content:
    new_line = '    <string name="%s">%s</string>\n' % (NEWKEY, STRINGS[NEWKEY])
    idx = content.rfind('</resources>')
    if idx == -1:
        raise RuntimeError("no </resources>")
    content = content[:idx] + new_line + content[idx:]
    inserted.append(NEWKEY)

with open(TF, 'w', encoding='utf-8', newline='\n') as f:
    f.write(content)

print("REPLACED_STRINGS", len([k for k in replaced if k in STRINGS]))
print("REPLACED_PLURALS", len([k for k in replaced if k in PLURALS]))
print("INSERTED", inserted)
